WITH combined_sales AS ( SELECT ss_promo_sk AS promo_sk, ss_net_profit AS net_profit, ss_ext_discount_amt AS discount_amt, ss_net_paid AS net_paid FROM store_sales WHERE ss_promo_sk IS NOT NULL UNION ALL SELECT ws_promo_sk AS promo_sk, ws_net_profit AS net_profit, ws_ext_discount_amt AS discount_amt, ws_net_paid AS net_paid FROM web_sales WHERE ws_promo_sk IS NOT NULL ), promo_agg AS ( SELECT promo_sk, SUM(net_profit) AS total_net_profit, SUM(discount_amt) AS total_discount, SUM(net_paid) AS total_sales, COUNT(*) AS txn_count FROM combined_sales GROUP BY promo_sk ) SELECT p.p_promo_id, p.p_promo_name, sd_start.d_date AS start_date, sd_end.d_date AS end_date, CASE WHEN CURRENT_DATE BETWEEN sd_start.d_date AND sd_end.d_date THEN 'Active' ELSE 'Inactive' END AS promo_status, pa.total_sales, pa.total_discount, pa.total_net_profit, CASE WHEN pa.total_sales > 0 THEN ROUND(pa.total_discount / pa.total_sales * 100, 2) ELSE 0 END AS discount_percent, DENSE_RANK() OVER (ORDER BY pa.total_net_profit DESC) AS profit_rank FROM promo_agg pa JOIN promotion p ON pa.promo_sk = p.p_promo_sk JOIN date_dim sd_start ON p.p_start_date_sk = sd_start.d_date_sk JOIN date_dim sd_end ON p.p_end_date_sk = sd_end.d_date_sk ORDER BY profit_rank LIMIT 100
